static int cmp(const void *a, const void *b) {
  return *(int *)a - *(int *)b;
}

int **pairSums(int *nums, int numsSize, int target, int *returnSize, int **returnColumnSizes) {
  qsort(nums, numsSize, sizeof(int), cmp);
  int **res = (int **)malloc(sizeof(int *) * (numsSize / 2 + 1));
  *returnColumnSizes = (int *)malloc(sizeof(int) * (numsSize / 2 + 1));
  *returnSize = 0;
  int i = 0, j = numsSize - 1;
  while (i < j) {
    int sum = nums[i] + nums[j];
    if (sum < target) {
      i++;
    } else if (sum > target) {
      j--;
    } else {
      res[*returnSize] = (int *)malloc(sizeof(int) * 2);
      res[*returnSize][0] = nums[i];
      res[*returnSize][1] = nums[j];
      (*returnColumnSizes)[*returnSize] = 2;
      (*returnSize)++;
      i++;
      j--;
    }
  }
  return res;
}

class Solution {
public:
  vector<vector<int>> pairSums(vector<int> &nums, int target) {
    sort(nums.begin(), nums.end());
    vector<vector<int>> res;
    int i = 0, j = nums.size() - 1;
    while (i < j) {
      int sum = nums[i] + nums[j];
      if (sum < target) {
        i++;
      } else if (sum > target) {
        j--;
      } else {
        res.push_back({nums[i], nums[j]});
        i++;
        j--;
      }
    }
    return res;
  }
};

func pairSums(nums []int, target int) [][]int {
	sort.Ints(nums)
	res := [][]int{}
	i, j := 0, len(nums)-1
	for i < j {
		sum := nums[i] + nums[j]
		if sum < target {
			i++
		} else if sum > target {
			j--
		} else {
			res = append(res, []int{nums[i], nums[j]})
			i++
			j--
		}
	}
	return res
}

class Solution {
  public List<List<Integer>> pairSums(int[] nums, int target) {
    Arrays.sort(nums);
    List<List<Integer>> res = new ArrayList<>();
    int i = 0, j = nums.length - 1;
    while (i < j) {
      int sum = nums[i] + nums[j];
      if (sum < target) {
        i++;
      } else if (sum > target) {
        j--;
      } else {
        res.add(Arrays.asList(nums[i], nums[j]));
        i++;
        j--;
      }
    }
    return res;
  }
}

class Solution:
    def pairSums(self, nums: List[int], target: int) -> List[List[int]]:
        nums.sort()
        res = []
        i, j = 0, len(nums) - 1
        while i < j:
            total = nums[i] + nums[j]
            if total < target:
                i += 1
            elif total > target:
                j -= 1
            else:
                res.append([nums[i], nums[j]])
                i += 1
                j -= 1
        return res

impl Solution {
  pub fn pair_sums(mut nums: Vec<i32>, target: i32) -> Vec<Vec<i32>> {
    nums.sort();
    let mut res = vec![];
    let mut i = 0i32;
    let mut j = nums.len() as i32 - 1;
    while i < j {
      let sum = nums[i as usize] + nums[j as usize];
      if sum < target {
        i += 1;
      } else if sum > target {
        j -= 1;
      } else {
        res.push(vec![nums[i as usize], nums[j as usize]]);
        i += 1;
        j -= 1;
      }
    }
    res
  }
}

const pairSums = (nums: number[], target: number): number[][] => {
  nums.sort((a, b) => a - b);
  const res: number[][] = [];
  let i = 0;
  let j = nums.length - 1;
  while (i < j) {
    const sum = nums[i] + nums[j];
    if (sum < target) {
      i++;
    } else if (sum > target) {
      j--;
    } else {
      res.push([nums[i], nums[j]]);
      i++;
      j--;
    }
  }
  return res;
};
